package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    // Columns: time, missing, job_id, task_idx, machine_id, event_type,
    // user, sched_cls, priority, cpu_requested, mem_requested, disk, restriction

    public long time;           // timestamp in microseconds
    public String missing;      // missing info field
    public long jobId;          // job ID
    public long taskIdx;        // task index within job
    public String machineId;    // machine ID (may be empty)
    public int eventType;       // 0=SUBMIT, 1=SCHEDULE, 2=EVICT, 3=FAIL, 4=FINISH, 5=KILL
    public String user;         // user (hashed)
    public int schedClass;      // scheduling class
    public int priority;        // task priority
    public double cpuRequested; // CPU requested
    public double memRequested; // memory requested
    public double disk;         // disk space requested
    public int restriction;     // different machines restriction

    public TaskEvent() {
    }

    public TaskEvent(long time, String missing, long jobId, long taskIdx, String machineId,
                     int eventType, String user, int schedClass, int priority,
                     double cpuRequested, double memRequested, double disk, int restriction) {
        this.time = time;
        this.missing = missing;
        this.jobId = jobId;
        this.taskIdx = taskIdx;
        this.machineId = machineId;
        this.eventType = eventType;
        this.user = user;
        this.schedClass = schedClass;
        this.priority = priority;
        this.cpuRequested = cpuRequested;
        this.memRequested = memRequested;
        this.disk = disk;
        this.restriction = restriction;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "time=" + time +
                ", jobId=" + jobId +
                ", taskIdx=" + taskIdx +
                ", eventType=" + eventType +
                '}';
    }
}

