package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.functions.FlatMapFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.functions.ReduceFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.TumblingEventTimeWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.util.Collector;

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Serializable;

public class LongestSessionPerJob extends AppBase {

    public static class TaskEventSource implements SourceFunction<TaskEvent> {
        private String filePath;
        private volatile boolean isRunning = true;

        public TaskEventSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (java.util.zip.GZIPInputStream gzip = new java.util.zip.GZIPInputStream(
                    new java.io.FileInputStream(filePath));
                 java.io.BufferedReader reader = new java.io.BufferedReader(
                         new java.io.InputStreamReader(gzip))) {

                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    String[] parts = line.split(",");
                    if (parts.length >= 13) {
                        try {
                            long time = Long.parseLong(parts[0]);
                            String missing = parts[1].isEmpty() ? "" : parts[1];
                            long jobId = Long.parseLong(parts[2]);
                            long taskIdx = Long.parseLong(parts[3]);
                            String machineId = parts[4].isEmpty() ? "" : parts[4];
                            int eventType = Integer.parseInt(parts[5]);
                            String user = parts[6].isEmpty() ? "" : parts[6];
                            int schedClass = parts[7].isEmpty() ? 0 : Integer.parseInt(parts[7]);
                            int priority = parts[8].isEmpty() ? 0 : Integer.parseInt(parts[8]);
                            double cpuRequested = parts[9].isEmpty() ? 0.0 : Double.parseDouble(parts[9]);
                            double memRequested = parts[10].isEmpty() ? 0.0 : Double.parseDouble(parts[10]);
                            double disk = parts[11].isEmpty() ? 0.0 : Double.parseDouble(parts[11]);
                            int restriction = parts[12].isEmpty() ? 0 : Integer.parseInt(parts[12]);

                            TaskEvent event = new TaskEvent(time, missing, jobId, taskIdx, machineId,
                                    eventType, user, schedClass, priority, cpuRequested, memRequested,
                                    disk, restriction);
                            ctx.collectWithTimestamp(event, time);
                        } catch (NumberFormatException e) {
                            // Skip malformed lines
                        }
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }

    public static class JobEventSource implements SourceFunction<JobEvent> {
        private String filePath;
        private volatile boolean isRunning = true;

        public JobEventSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (java.util.zip.GZIPInputStream gzip = new java.util.zip.GZIPInputStream(
                    new java.io.FileInputStream(filePath));
                 java.io.BufferedReader reader = new java.io.BufferedReader(
                         new java.io.InputStreamReader(gzip))) {

                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    String[] parts = line.split(",");
                    if (parts.length >= 8) {
                        try {
                            long time = Long.parseLong(parts[0]);
                            String missing = parts[1].isEmpty() ? "" : parts[1];
                            long jobId = Long.parseLong(parts[2]);
                            int eventType = Integer.parseInt(parts[3]);
                            String user = parts[4].isEmpty() ? "" : parts[4];
                            int schedClass = parts[5].isEmpty() ? 0 : Integer.parseInt(parts[5]);
                            String jobName = parts[6].isEmpty() ? "" : parts[6];
                            String logicalJobName = parts[7].isEmpty() ? "" : parts[7];

                            JobEvent event = new JobEvent(time, missing, jobId, eventType, user,
                                    schedClass, jobName, logicalJobName);
                            ctx.collectWithTimestamp(event, time);
                        } catch (NumberFormatException e) {
                            // Skip malformed lines
                        }
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }

    public static class FileSink extends SinkFunction<Tuple2<Long, Integer>> {
        private String outputPath;

        public FileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void invoke(Tuple2<Long, Integer> value, Context context) throws Exception {
            synchronized (this) {
                try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputPath, true))) {
                    writer.write("(" + value.f0 + "," + value.f1 + ")\n");
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    public static class StageState implements Serializable {
        public long jobId;
        public long firstSubmitTime;
        public int taskCount;

        public StageState() {
        }

        public StageState(long jobId, long firstSubmitTime, int taskCount) {
            this.jobId = jobId;
            this.firstSubmitTime = firstSubmitTime;
            this.taskCount = taskCount;
        }
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final long sesssize = params.getLong("sesssize", 600) * 1_000_000L; // Convert to microseconds

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // Read task events (only SUBMIT events matter)
        SourceFunction<TaskEvent> taskSource = new TaskEventSource(taskInput);
        SourceFunction<TaskEvent> finalTaskSource = taskSourceOrTest(taskSource);

        // Read job events
        SourceFunction<JobEvent> jobSource = new JobEventSource(jobInput);
        SourceFunction<JobEvent> finalJobSource = jobSourceOrTest(jobSource);

        // Process task events - keep only SUBMIT events (event type 0)
        var taskStream = env.addSource(finalTaskSource)
                .name("task-source")
                .filter(event -> event.eventType == 0) // Only SUBMIT events
                .name("filter-submit-events")
                .keyBy(event -> event.jobId)
                .name("key-by-job");

        // Process job events - keep only FINISH events (event type 4)
        var jobStream = env.addSource(finalJobSource)
                .name("job-source")
                .filter(event -> event.eventType == 4) // Only FINISH events
                .name("filter-finish-events")
                .map(event -> Tuple2.of(event.jobId, event.time))
                .name("extract-job-finish");

        // Apply session window to group task submits
        var stageResults = taskStream
                .window(TumblingEventTimeWindows.of(Time.microseconds(600_000_000L))) // Use fixed window
                .process(new org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction<
                        TaskEvent,
                        Tuple2<Long, Integer>,
                        Long,
                        org.apache.flink.streaming.api.windowing.windows.TimeWindow>() {

                    private java.util.Map<Long, java.util.List<Long>> jobToSubmitTimes = new java.util.HashMap<>();

                    @Override
                    public void process(Long jobId,
                                      org.apache.flink.streaming.api.windowing.windows.TimeWindow context,
                                      Iterable<TaskEvent> elements,
                                      Collector<Tuple2<Long, Integer>> out) {
                        // Group submit times by job
                        if (!jobToSubmitTimes.containsKey(jobId)) {
                            jobToSubmitTimes.put(jobId, new java.util.ArrayList<>());
                        }

                        for (TaskEvent event : elements) {
                            jobToSubmitTimes.get(jobId).add(event.time);
                        }

                        // Identify stages based on 10-minute gaps
                        java.util.List<Long> submitTimes = jobToSubmitTimes.get(jobId);
                        if (submitTimes.isEmpty()) {
                            return;
                        }

                        java.util.Collections.sort(submitTimes);

                        int maxTasksInStage = 0;
                        int currentStageCount = 1;

                        for (int i = 1; i < submitTimes.size(); i++) {
                            long timeDiff = submitTimes.get(i) - submitTimes.get(i - 1);
                            if (timeDiff > sesssize) {
                                // New stage starts
                                maxTasksInStage = Math.max(maxTasksInStage, currentStageCount);
                                currentStageCount = 1;
                            } else {
                                currentStageCount++;
                            }
                        }
                        maxTasksInStage = Math.max(maxTasksInStage, currentStageCount);

                        out.collect(Tuple2.of(jobId, maxTasksInStage));
                    }
                })
                .name("identify-stages");

        // Write results to file
        SinkFunction<Tuple2<Long, Integer>> sink = new FileSink(outputPath);
        SinkFunction<Tuple2<Long, Integer>> finalSink = sinkOrTest(sink);

        stageResults
                .addSink(finalSink)
                .name("write-results");

        env.execute("LongestSessionPerJob");
    }

}

